import cgi
import http.server
import json
def task_func():
    class JSONPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_json_response(self, status_code, payload):
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            self.wfile.write(json.dumps(payload).encode("utf-8"))
        def do_POST(self):
            content_type = self.headers.get("Content-Type", "")
            if content_type != "application/json":
                payload = {"status": "error", "message": "Content-Type header is not application/json"}
                self._send_json_response(400, payload)
                return
            content_length = self.headers.get("Content-Length")
            try:
                length = int(content_length) if content_length is not None else 0
            except ValueError:
                length = 0
            body = self.rfile.read(length) if length > 0 else b""
            try:
                data = json.loads(body.decode("utf-8") if body else "{}")
            except json.JSONDecodeError:
                payload = {"status": "error", "message": "No data received"}
                self._send_json_response(400, payload)
                return
            if "data" not in data:
                payload = {"status": "error", "message": "No data received"}
                self._send_json_response(400, payload)
                return
            payload = {"status": "success", "message": "Data received successfully."}
            self._send_json_response(200, payload)
    return JSONPostHandler
