import json
import re
import pandas as pd
def task_func(json_str):
    if not json_str or not str(json_str).strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict) or not data:
        return pd.DataFrame()
    def is_number(s):
        try:
            float(s)
            return True
        except (ValueError, TypeError):
            return False
    normalized = {}
    for k, v in data.items():
        if isinstance(v, (int, float)):
            normalized[k] = float(v) * 2.0
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2.0)
                elif isinstance(item, str) and is_number(item):
                    new_list.append(float(item) * 2.0)
                else:
                    new_list.append(item)
            normalized[k] = new_list
        elif isinstance(v, str):
            nums = re.findall(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', v)
            if not nums:
                normalized[k] = v
            else:
                if is_number(v.strip()):
                    normalized[k] = float(v) * 2.0
                else:
                    def repl(match):
                        num = match.group(0)
                        return str(float(num) * 2.0)
                    normalized[k] = re.sub(r'[-+]?\d*\.?\d+(?:[eE][-+]?\d+)?', repl, v)
        else:
            normalized[k] = v
    try:
        df = pd.DataFrame(normalized)
        if df.shape[0] == 0:
            df = pd.DataFrame([normalized])
    except ValueError:
        df = pd.DataFrame([normalized])
